// Vercel: the framework's own handler, deployed unchanged.
export const maxDuration = 60; // seconds; the platform caps it
export async function POST(req: Request) {
  const { prompt } = await req.json();
  // Active CPU bills while this code runs, not while it waits:
  const upstream = await fetch('https://api.example.com/v1/chat', {
    method: 'POST',
    body: JSON.stringify({ prompt }),
    headers: { 'content-type': 'application/json' },
  });
  // Here it breaks: default duration limits kill long streams. Set maxDuration
  // and check the platform ceiling before shipping a 5-minute job.
  return new Response(upstream.body, { headers: { 'content-type': 'text/event-stream' } });
}

